<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import Activity from '@lucide/vue/dist/esm/icons/activity.mjs'
import BarChart3 from '@lucide/vue/dist/esm/icons/chart-bar.mjs'
import CalendarDays from '@lucide/vue/dist/esm/icons/calendar-days.mjs'
import ChevronDown from '@lucide/vue/dist/esm/icons/chevron-down.mjs'
import CircleAlert from '@lucide/vue/dist/esm/icons/circle-alert.mjs'
import CircleDollarSign from '@lucide/vue/dist/esm/icons/circle-dollar-sign.mjs'
import GraduationCap from '@lucide/vue/dist/esm/icons/graduation-cap.mjs'
import HeartPulse from '@lucide/vue/dist/esm/icons/heart-pulse.mjs'
import RefreshCw from '@lucide/vue/dist/esm/icons/refresh-cw.mjs'
import Search from '@lucide/vue/dist/esm/icons/search.mjs'
import SlidersHorizontal from '@lucide/vue/dist/esm/icons/sliders-horizontal.mjs'
import Store from '@lucide/vue/dist/esm/icons/store.mjs'
import Target from '@lucide/vue/dist/esm/icons/target.mjs'
import TrendingUp from '@lucide/vue/dist/esm/icons/trending-up.mjs'
import UserRound from '@lucide/vue/dist/esm/icons/user-round.mjs'
import UsersRound from '@lucide/vue/dist/esm/icons/users-round.mjs'
import { queryEmployeeDashboard, queryEmployeeDashboardScope } from '@/services/employeeDashboardApi'

function emptyDashboardData() {
  return {
    overview: { cards: [], education: [], ages: [], tenure: [] },
    roles: [],
    performance: { cards: [], categories: [], trend: [], trendLabels: [], branches: [] },
    target: { cards: [], trend: [], trendLabels: [], branches: [] },
    scopes: {},
    role_health: { active_count: null, quota: null, gap: null, fill_rate: null, turnover_rate: null }
  }
}

function isRecord(value) { return value && typeof value === 'object' && !Array.isArray(value) }
function normalizeDashboardPayload(payload) {
  const source = isRecord(payload?.dashboard) ? payload.dashboard : (isRecord(payload) ? payload : {})
  const blank = emptyDashboardData()
  return {
    ...blank,
    ...source,
    overview: { ...blank.overview, ...(isRecord(source.overview) ? source.overview : {}) },
    performance: { ...blank.performance, ...(isRecord(source.performance) ? source.performance : {}) },
    target: { ...blank.target, ...(isRecord(source.target) ? source.target : {}) },
    role_health: { ...blank.role_health, ...(isRecord(source.role_health) ? source.role_health : {}) },
    roles: Array.isArray(source.roles) ? source.roles : [],
    scopes: isRecord(source.scopes) ? source.scopes : {}
  }
}

function hasDashboardData(value) {
  if (!value || value.has_data === false || value.empty === true) return false
  return Boolean(value.overview.cards.length || value.roles.length || value.performance.cards.length || value.target.cards.length)
}

const data = ref(emptyDashboardData()); const active = ref('overview'); const period = ref('month'); const startDate = ref('2026-08-01'); const endDate = ref('2026-08-21'); const scope = ref('总部'); const scopeSelection = ref({ org_id: 0, store_id: 0, store_ids: '' }); const role = ref('全部岗位'); const state = ref('loading'); const loading = ref(true); const scopeOpen = ref(false); const notice = ref('正在加载员工看板'); const scopeTree = ref([]); let requestSequence = 0
const pageSize = 10; const branchPage = ref(1); const targetPage = ref(1)
const sections = [{ key: 'overview', label: '人员概况', icon: UsersRound }, { key: 'roles', label: '美容师与岗位结构', icon: UserRound }, { key: 'performance', label: '业绩与服务分析', icon: TrendingUp }, { key: 'target', label: '消耗与目标分析', icon: Target }]
const title = computed(() => sections.find((item) => item.key === active.value)?.label || '员工看板'); const dataAsOf = computed(() => data.value.data_as_of || data.value.dataAsOf || '接口返回后显示'); const eduTotal = computed(() => data.value.overview.education.reduce((s, i) => s + Number(i.value || 0), 0)); const max = (key, list) => Math.max(...list.map((i) => Number(i[key] || 0)), 1); const maxAge = computed(() => max('value', data.value.overview.ages)); const maxTenure = computed(() => max('value', data.value.overview.tenure)); const maxRole = computed(() => max('value', data.value.roles)); const maxBranch = computed(() => max('value', data.value.performance.branches)); const maxTarget = computed(() => max('target', data.value.target.branches)); const eduGradient = computed(() => { let n = 0; return data.value.overview.education.map((i) => { const start = n; n += eduTotal.value ? i.value / eduTotal.value * 100 : 0; return `${i.color} ${start}% ${n}%` }).join(', ') })
const performanceTotal = computed(() => data.value.performance.cards.find((card) => card.key === 'performance_total' || card.key === 'amount') || {}); const consumptionTotal = computed(() => data.value.target.cards.find((card) => card.key === 'consumption_amount' || card.key === 'consumption') || {}); const consumptionRatio = computed(() => data.value.target.cards.find((card) => card.key === 'consumption_ratio' || card.key === 'consumptionRate') || {}); const activeStaff = computed(() => data.value.overview.cards.find((card) => card.key === 'active_staff' || card.key === 'total') || {})
const roleHealth = computed(() => data.value.role_health || {})
const branchPages = computed(() => Math.max(1, Math.ceil(data.value.performance.branches.length / pageSize)))
const targetPages = computed(() => Math.max(1, Math.ceil(data.value.target.branches.length / pageSize)))
const pagedBranches = computed(() => data.value.performance.branches.slice((branchPage.value - 1) * pageSize, branchPage.value * pageSize))
const pagedTargets = computed(() => data.value.target.branches.slice((targetPage.value - 1) * pageSize, targetPage.value * pageSize))
function changePage(kind, page) { if (kind === 'branch') branchPage.value = Math.min(branchPages.value, Math.max(1, page)); else targetPage.value = Math.min(targetPages.value, Math.max(1, page)) }
function num(v) { return v === null || v === undefined || v === '' ? '--' : Number(v).toLocaleString('zh-CN', { maximumFractionDigits: 1 }) }; function money(v) { return v === null || v === undefined || v === '' ? '--' : `¥${Number(v).toLocaleString('zh-CN')}` }; function pct(v) { return v === null || v === undefined ? '--' : `${Number(v).toFixed(1).replace(/\.0$/, '')}%` }; function periodLabel() { return period.value === 'month' ? '2026年8月' : period.value === 'year' ? '2026年1月–8月' : `${startDate.value} 至 ${endDate.value}` }
async function query() {
  const sequence = ++requestSequence
  loading.value = true
  state.value = 'loading'
  notice.value = '正在按当前条件加载员工看板'
  try {
    const year = new Date().getFullYear()
    const result = await queryEmployeeDashboard({
      period: period.value,
      start_date: period.value === 'custom' ? startDate.value : (period.value === 'year' ? `${year}-01-01` : undefined),
      end_date: period.value === 'custom' ? endDate.value : (period.value === 'year' ? new Date().toISOString().slice(0, 10) : undefined),
      org_id: scopeSelection.value.org_id || undefined,
      store_id: scopeSelection.value.store_id || undefined,
      store_ids: scopeSelection.value.store_ids || undefined,
      role: role.value === '全部岗位' ? undefined : role.value
    })
    if (sequence !== requestSequence) return
    const normalized = normalizeDashboardPayload(result)
    data.value = normalized
    branchPage.value = 1
    targetPage.value = 1
    loading.value = false
    state.value = hasDashboardData(normalized) ? 'normal' : 'empty'
    notice.value = hasDashboardData(normalized) ? `已更新${periodLabel()}的员工看板` : '当前条件暂无员工看板数据'
  } catch (error) {
    if (sequence !== requestSequence) return
    loading.value = false
    state.value = 'error'
    notice.value = error?.message || '员工看板加载失败，请重试'
  }
}
function selectScope(v, node = null) {
  scope.value = v
  scopeSelection.value = {
    org_id: Number(node?.id || node?.org_id || 0) || 0,
    store_id: Number(node?.store_id || 0) || 0,
    store_ids: Array.isArray(node?.store_ids) ? node.store_ids.join(',') : ''
  }
  scopeOpen.value = false
  query()
}
function x(i, count) { return count < 2 ? 0 : i / (count - 1) * 100 }; function y(v, values) { return 100 - Number(v || 0) / Math.max(...values, 1) * 82 - 5 }; function line(values) { return values.map((v, i) => `${x(i, values.length)},${y(v, values)}`).join(' ') }
function setResponsiveRoot(enabled) { const root = document.documentElement; const body = document.body; if (enabled) { root.classList.add('employee-dashboard-document'); body.classList.add('employee-dashboard-document'); root.style.setProperty('min-width', '0', 'important'); body.style.setProperty('min-width', '0', 'important'); body.style.setProperty('overflow-y', 'auto', 'important') } else { root.classList.remove('employee-dashboard-document'); body.classList.remove('employee-dashboard-document'); root.style.removeProperty('min-width'); body.style.removeProperty('min-width'); body.style.removeProperty('overflow-y') } }
onMounted(async () => {
  setResponsiveRoot(true)
  try {
    const result = await queryEmployeeDashboardScope()
    const tree = result?.tree || result?.scope?.tree || []
    if (Array.isArray(tree)) scopeTree.value = tree
  } catch (_) {
    scopeTree.value = []
  }
  query()
}); onBeforeUnmount(() => { setResponsiveRoot(false); requestSequence += 1 })
</script>
<template>
  <main class="employee-dashboard"><header class="hero"><div><span><BarChart3 :size="15" />集团经营数据中心</span><h1>员工看板</h1><p>人员结构、服务产出与目标完成情况，按当前权限范围统一查看。</p></div><aside><i></i>{{ notice }}<small>数据截至 {{ dataAsOf }}</small></aside></header>
  <section class="toolbar"><button class="scope" @click="scopeOpen = !scopeOpen"><Store :size="15" />{{ scope }} / {{ scope === '总部' ? '全部组织' : '可见门店' }}<ChevronDown :size="14" /></button><div v-if="scopeOpen" class="scope-menu"><b>选择组织范围</b><button v-for="node in (scopeTree[0]?.children || scopeTree)" :key="node.id || node.label || node.name" @click="selectScope(node.label || node.name, node)">{{ node.label || node.name }}<small>{{ node.stores?.length || node.children?.length || 0 }}个下级组织</small></button><button @click="selectScope('总部')">总部<small>全部组织</small></button></div><div class="periods"><button :class="{ active: period === 'month' }" @click="period = 'month'">本月</button><button :class="{ active: period === 'year' }" @click="period = 'year'">本年</button><button :class="{ active: period === 'custom' }" @click="period = 'custom'">自定义</button></div><label v-if="period === 'custom'"><CalendarDays :size="14" /><input v-model="startDate" type="date" />至<input v-model="endDate" type="date" /></label><label><SlidersHorizontal :size="14" />岗位<select v-model="role"><option>全部岗位</option><option>美容师</option><option>顾问</option><option>店长</option></select></label><div class="actions"><button class="primary" :disabled="loading" @click="query"><Search :size="14" />查询</button><button :disabled="loading" @click="query"><RefreshCw :size="14" :class="{ spin: loading }" />刷新</button></div></section>
  <div class="layout"><aside class="nav"><strong>员工看板<small>数据分析</small></strong><button v-for="item in sections" :key="item.key" :class="{ active: active === item.key }" @click="active = item.key"><component :is="item.icon" :size="15" />{{ item.label }}</button><p><CircleAlert :size="13" />指标按当前权限范围统计。</p></aside><section v-if="loading" class="state"><RefreshCw :size="24" class="spin" /><b>正在加载员工看板</b><span>正在整理当前筛选条件下的数据</span></section><section v-else-if="state === 'empty'" class="state"><UsersRound :size="28" /><b>暂无员工看板数据</b><span>请调整组织、岗位或日期范围后重新查询</span><button class="primary" @click="query">重新查询</button></section><section v-else-if="state === 'error'" class="state error"><CircleAlert :size="28" /><b>员工看板加载失败</b><span>请检查筛选条件或稍后重试</span><button class="primary" @click="query">重新查询</button></section><section v-else class="content"><div class="heading"><div><span>{{ periodLabel() }} · {{ scope }}</span><h2>{{ title }}</h2></div><small>列名取值来源：统一员工报表口径</small></div>
    <template v-if="true"><div class="metrics six"><article v-for="c in data.overview.cards" :key="c.key" class="metric" :class="c.tone"><div><UsersRound :size="15" />{{ c.label }}</div><strong>{{ num(c.value) }}<small>{{ c.unit }}</small></strong><p>{{ c.source }}</p></article></div><div class="panels two"><article class="panel"><header><span><GraduationCap :size="14" />学历结构<h3>员工学历分布</h3></span></header><div class="donut-layout"><div class="donut" :style="{ background: `conic-gradient(${eduGradient})` }"><b>{{ eduTotal }}<small>员工</small></b></div><div class="legend"><div v-for="i in data.overview.education" :key="i.label"><i :style="{ background: i.color }"></i>{{ i.label }}<b>{{ i.value }}</b><em>{{ pct(i.value / eduTotal * 100) }}</em></div></div></div></article><article class="panel"><header><span><UserRound :size="14" />年龄分布<h3>员工年龄段</h3></span></header><div class="bars"><div v-for="i in data.overview.ages" :key="i.label"><span>{{ i.label }}</span><i><b :style="{ width: `${i.value / maxAge * 100}%` }"></b></i><em>{{ i.value }}</em></div></div></article></div><article class="panel"><header><span><Activity :size="14" />工龄分布<h3>员工在岗年限</h3></span></header><div class="bars five"><div v-for="i in data.overview.tenure" :key="i.label"><span>{{ i.label }}</span><i><b :style="{ width: `${i.value / maxTenure * 100}%` }"></b></i><em>{{ i.value }}人</em></div></div></article></template>
    <template v-if="true"><div class="metrics six"><article v-for="c in data.overview.cards.slice(3)" :key="c.key" class="metric" :class="c.tone"><div><UserRound :size="15" />{{ c.label }}</div><strong>{{ num(c.value) }}<small>{{ c.unit }}</small></strong><p>{{ c.source }}</p></article><article class="metric teal"><div><HeartPulse :size="15" />流失率</div><strong>{{ pct(roleHealth.turnover_rate) }}</strong><p>期间流失人数 / 期间平均在职人数</p></article></div><div class="panels two"><article class="panel"><header><span><UsersRound :size="14" />层级结构<h3>岗位人数与编制</h3></span></header><div class="role-list"><div v-for="i in data.roles" :key="i.label"><span>{{ i.label }}</span><i><b :style="{ width: `${i.value / maxRole * 100}%`, background: i.color }"></b></i><strong>{{ i.value }}人</strong><em>编制 {{ i.quota }}</em></div></div></article><article class="panel"><header><span><HeartPulse :size="14" />岗位健康<h3>岗位满岗情况</h3></span></header><div class="ring">{{ pct(roleHealth.fill_rate) }}<small>整体满岗率</small></div><dl><div><dt>在职人数</dt><dd>{{ roleHealth.active_count == null ? '--' : `${roleHealth.active_count}人` }}</dd></div><div><dt>岗位编制</dt><dd>{{ roleHealth.quota == null ? '--' : `${roleHealth.quota}人` }}</dd></div><div><dt>缺口岗位</dt><dd>{{ roleHealth.gap == null ? '--' : `${roleHealth.gap}人` }}</dd></div></dl></article></div></template>
    <template v-if="true"><div class="metrics four"><article v-for="c in data.performance.cards" :key="c.key" class="metric" :class="c.tone"><div><TrendingUp :size="15" />{{ c.label }}</div><strong>{{ c.unit === '元' ? money(c.value) : num(c.value) }}<small v-if="c.unit !== '元'">{{ c.unit }}</small></strong><p>{{ c.source }}</p></article></div><div class="panels two"><article class="panel"><header><span><TrendingUp :size="14" />业绩趋势<h3>月度业绩总额</h3></span></header><div class="line"><svg viewBox="0 0 100 100" preserveAspectRatio="none"><polyline :points="line(data.performance.trend)" /><circle v-for="(v, i) in data.performance.trend" :key="i" :cx="x(i, data.performance.trend.length)" :cy="y(v, data.performance.trend)" r="1.8" /></svg><div><span v-for="l in data.performance.trendLabels" :key="l">{{ l }}</span></div></div></article><article class="panel"><header><span><CircleDollarSign :size="14" />业绩结构<h3>按业绩分类</h3></span></header><div class="legend large"><div v-for="i in data.performance.categories" :key="i.label"><i :style="{ background: i.color }"></i>{{ i.label }}<b>{{ money(i.value) }}</b><em>{{ pct(i.percent) }}</em></div></div></article></div><article class="panel"><header><span><Store :size="14" />组织结构<h3>分公司业绩与人员</h3></span></header><div class="branch-list"><div v-for="i in pagedBranches" :key="i.label"><span>{{ i.label }}</span><i><b :style="{ width: `${i.value / maxBranch * 100}%`, background: i.color }"></b></i><strong>{{ money(i.value) }}</strong><em>{{ i.staff }}人</em></div></div><div v-if="branchPages > 1" class="list-pagination"><button :disabled="branchPage === 1" @click="changePage('branch', branchPage - 1)">上一页</button><span>第 {{ branchPage }} / {{ branchPages }} 页，共 {{ data.performance.branches.length }} 条</span><button :disabled="branchPage === branchPages" @click="changePage('branch', branchPage + 1)">下一页</button></div></article></template>
    <template v-if="true"><div class="metrics four"><article v-for="c in data.target.cards" :key="c.key" class="metric" :class="c.tone"><div><Target :size="15" />{{ c.label }}</div><strong>{{ c.unit === '元' ? money(c.value) : num(c.value) }}<small v-if="c.unit !== '元'">{{ c.unit }}</small></strong><p>{{ c.source }}</p></article></div><div class="panels two"><article class="panel"><header><span><Activity :size="14" />目标进度<h3>目标完成率趋势</h3></span></header><div class="line green"><svg viewBox="0 0 100 100" preserveAspectRatio="none"><polyline :points="line(data.target.trend)" /><circle v-for="(v, i) in data.target.trend" :key="i" :cx="x(i, data.target.trend.length)" :cy="y(v, data.target.trend)" r="1.8" /></svg><div><span v-for="l in data.target.trendLabels" :key="l">{{ l }}</span></div></div></article><article class="panel"><header><span><CircleDollarSign :size="14" />消耗结构<h3>消耗与销售对比</h3></span></header><div class="comparison"><b>{{ pct(consumptionRatio.value) }}<small>消耗/销售</small></b><p>销售业绩 {{ money(performanceTotal.value) }}<br />消耗业绩 {{ money(consumptionTotal.value) }}</p></div></article></div><article class="panel"><header><span><Store :size="14" />目标完成<h3>分公司消耗业绩与目标</h3></span></header><div class="target-list"><div v-for="i in pagedTargets" :key="i.label"><span>{{ i.label }}</span><i><b :style="{ width: `${i.target / maxTarget * 100}%` }"></b><em :style="{ width: `${i.consumption / maxTarget * 100}%` }"></em></i><small>{{ money(i.consumption) }} / {{ money(i.target) }}</small><strong>{{ pct(i.completion) }}</strong></div></div><div v-if="targetPages > 1" class="list-pagination"><button :disabled="targetPage === 1" @click="changePage('target', targetPage - 1)">上一页</button><span>第 {{ targetPage }} / {{ targetPages }} 页，共 {{ data.target.branches.length }} 条</span><button :disabled="targetPage === targetPages" @click="changePage('target', targetPage + 1)">下一页</button></div></article></template>
  </section></div><footer class="footer"><span>当前查看：{{ title }} · {{ scope }}</span><span>指标解释均使用业务语言。</span></footer></main>
</template>
